// ── Virtual Proxy: lazy image loading ────────────────────────────
class RealImage {
  constructor(filename) {
    this.filename = filename;
    this._load(); // expensive!
  }
  _load() {
    console.log(`[RealImage] Loading ${this.filename} from disk...`);
    this.data = `<binary data of ${this.filename}>`;
  }
  display() { console.log(`[RealImage] Displaying ${this.filename}`); }
  getSize() { return 1024; }
}

class ImageProxy {
  constructor(filename) {
    this.filename = filename;
    this._real = null; // NOT loaded yet
  }
  _getRealImage() {
    if (!this._real) this._real = new RealImage(this.filename); // lazy
    return this._real;
  }
  display() { this._getRealImage().display(); }
  getSize() {
    // Can answer without loading the real image!
    return this._real ? this._real.getSize() : 0;
  }
}

const img = new ImageProxy('hero.png');
console.log(`Size before display: ${img.getSize()}`); // 0 — not loaded
img.display(); // [RealImage] Loading hero.png... then displays
img.display(); // [RealImage] Displaying hero.png — no reload!

