// ── Protection Proxy: permission-based access ─────────────────────
class SecureFileService {
  readFile(path) { return `Contents of ${path}`; }
  deleteFile(path) { console.log(`[FileService] Deleted ${path}`); }
}

class SecureFileProxy {
  constructor(user) {
    this._service = new SecureFileService();
    this._user = user;
  }
  readFile(path) {
    if (!this._user.permissions.includes('read')) throw new Error('Access denied: read');
    return this._service.readFile(path);
  }
  deleteFile(path) {
    if (!this._user.permissions.includes('admin')) throw new Error('Access denied: admin');
    this._service.deleteFile(path);
  }
}

const readOnlyUser  = { name: 'Alice', permissions: ['read'] };
const adminUser     = { name: 'Bob',   permissions: ['read', 'admin'] };

const aliceProxy = new SecureFileProxy(readOnlyUser);
console.log(aliceProxy.readFile('/etc/config'));    // Contents of /etc/config
try { aliceProxy.deleteFile('/etc/config'); } catch (e) { console.log(e.message); }
// Access denied: admin

const bobProxy = new SecureFileProxy(adminUser);
bobProxy.deleteFile('/etc/config'); // [FileService] Deleted /etc/config

console.log('');

// ── ES6 Proxy: language-level interception ────────────────────────
const handler = {
  get(target, prop) {
    if (prop in target) {
      console.log(`[ES6 Proxy] Getting '${prop}'`);
      return target[prop];
    }
    return `Property '${prop}' not found`;
  },
  set(target, prop, value) {
    console.log(`[ES6 Proxy] Setting '${prop}' = ${value}`);
    target[prop] = value;
    return true;
  },
};

const original = { x: 10, y: 20 };
const proxied  = new Proxy(original, handler);

