// ── Structural skeleton ──────────────────────────────────────────

// 1. Subject Interface
class Subject {
  request() { throw new Error('Not implemented'); }
}

// 2. Real Subject
class RealSubject extends Subject {
  request() {
    return 'RealSubject: handled the request.';
  }
}

// 3. Proxy
class ProxySubject extends Subject {
  constructor() {
    super();
    this._real = null;
  }
  _checkAccess() {
    // Protection: return false to block
    console.log('[Proxy] Checking access...');
    return true;
  }
  _logCall() {
    console.log('[Proxy] Logging time of request.');
  }
  request() {
    if (!this._checkAccess()) return 'Blocked';
    // Lazy init (Virtual Proxy)
    if (!this._real) this._real = new RealSubject();
    const result = this._real.request();
    this._logCall();
    return result;
  }
}

function clientCode(subject) {
  console.log(subject.request());
}

clientCode(new ProxySubject());
// [Proxy] Checking access...
// [Proxy] Logging time of request.
// RealSubject: handled the request.

// ── Caching proxy pattern ────────────────────────────────────────
class CachingProxy {
  constructor(realService) {
    this._service = realService;
    this._cache   = new Map();
  }
  getData(key) {
    if (this._cache.has(key)) {
      console.log(`[Cache] HIT: ${key}`);
      return this._cache.get(key);
    }
    const result = this._service.getData(key);
    this._cache.set(key, result);
    console.log(`[Cache] MISS stored: ${key}`);
    return result;
  }
}
